from fastapi import FastAPI, HTTPException

app = FastAPI(title="Crestline Shipments")

FAKE_DB = {7731: {"id": 7731, "status": "in_transit", "events": ["picked_up"]}}

@app.get("/health")
def health():
    return {"ok": True}

@app.get("/shipments/{shipment_id}")        # path parameter
def get_shipment(shipment_id: int, include_events: bool = False):  # query param
    shipment = FAKE_DB.get(shipment_id)
    if shipment is None:
        raise HTTPException(status_code=404, detail="Shipment not found")
    if not include_events:
        return {k: v for k, v in shipment.items() if k != "events"}
    return shipment

