import os
from fastapi import APIRouter, Depends, FastAPI, Header, HTTPException

VALID_KEYS = set(os.environ.get("API_KEYS", "dev-key").split(","))

def require_key(x_api_key: str = Header(...)):      # reads X-API-Key header
    if x_api_key not in VALID_KEYS:
        raise HTTPException(status_code=401, detail="Invalid API key")
    return x_api_key

def get_db():
    db = SessionLocal()          # e.g. a SQLAlchemy session factory
    try:
        yield db                 # the endpoint runs while we are paused here
    finally:
        db.close()               # always runs after the response

router = APIRouter(prefix="/v1", dependencies=[Depends(require_key)])

@router.get("/accounts/{account_id}")
def get_account(account_id: int, db=Depends(get_db)):
    return db.get(Account, account_id)

app = FastAPI()
app.include_router(router)

import httpx, requests
from fastapi import FastAPI
from fastapi.concurrency import run_in_threadpool

app = FastAPI()
client = httpx.AsyncClient(timeout=10)   # reuse one client for connection pooling

@app.get("/bad/{sid}")
async def bad(sid: str):
    return requests.get(f"https://carrier.example/track/{sid}").json()  # BLOCKS the loop

@app.get("/good/{sid}")
async def good(sid: str):
    r = await client.get(f"https://carrier.example/track/{sid}")    # frees the loop
    return r.json()

@app.get("/legacy/{sid}")
async def legacy(sid: str):
    # Blocking SDK you cannot replace: push it to a worker thread
    return await run_in_threadpool(legacy_sdk.track, sid)

