from collections import Counter

def bpe_train(words: list[str], merges: int):
    # Start with each word as a tuple of characters
    corpus = Counter(tuple(w) for w in words)
    rules = []
    for _ in range(merges):
        pairs = Counter()
        for word, freq in corpus.items():
            for a, b in zip(word, word[1:]):
                pairs[(a, b)] += freq             # count adjacent pairs
        if not pairs:
            break
        best = max(pairs, key=pairs.get)          # most frequent pair
        rules.append(best)
        new = Counter()
        for word, freq in corpus.items():
            out, i = [], 0
            while i < len(word):
                if i + 1 < len(word) and (word[i], word[i+1]) == best:
                    out.append(word[i] + word[i+1]); i += 2   # merge
                else:
                    out.append(word[i]); i += 1
            new[tuple(out)] += freq
        corpus = new
    return rules, corpus

rules, corpus = bpe_train(["refund"]*5 + ["refunded"]*3 + ["fund"]*2, merges=5)
