import numpy as np

def rms_norm(x, gain, eps=1e-6):
    rms = np.sqrt((x ** 2).mean(axis=-1, keepdims=True) + eps)
    return x / rms * gain                               # scale by learned gain

def silu(z):
    return z / (1 + np.exp(-z))

def ffn(x, W_up, W_gate, W_down):
    # SwiGLU-style feed-forward used by many recent models
    return (silu(x @ W_gate) * (x @ W_up)) @ W_down

def decoder_layer(x, p):
    x = x + attention(rms_norm(x, p["g1"]), p)          # residual 1
    x = x + ffn(rms_norm(x, p["g2"]),                   # residual 2
                p["W_up"], p["W_gate"], p["W_down"])
    return x

