KEEP_FIELDS = {"sensor_id", "reading", "unit", "timestamp", "status"}

def trim_tool_output(result: dict) -> dict:
    # Keep only fields the model needs; full result is logged elsewhere
    return {k: v for k, v in result.items() if k in KEEP_FIELDS}

def compact_history(history: list[dict], keep_last: int = 6) -> list[dict]:
    if len(history) <= keep_last:
        return history
    old, recent = history[:-keep_last], history[-keep_last:]
    summary = summarize(old)   # an LLM call: keep facts, decisions, open questions
    # Keep the summary as the first user turn so roles still alternate
    return [{"role": "user", "content": f"<summary_of_earlier_turns>\n{summary}\n</summary_of_earlier_turns>"},
            {"role": "assistant", "content": "Understood."}] + recent

from dataclasses import dataclass, field

@dataclass
class Bullet:
    id: str                  # e.g. "err-004"
    section: str             # "strategies" | "errors" | "tools"
    text: str
    helpful: int = 0
    harmful: int = 0

@dataclass
class Playbook:
    bullets: dict[str, Bullet] = field(default_factory=dict)

    def render(self) -> str:
        # Turn the data into prompt text for the Generator
        lines = ["## PLAYBOOK"]
        for b in sorted(self.bullets.values(), key=lambda b: (b.section, b.id)):
            lines.append(f"[{b.id}] helpful={b.helpful} harmful={b.harmful}\n  {b.text}")
        return "\n".join(lines)

pb = Playbook()
pb.bullets["err-004"] = Bullet("err-004", "errors",
    "Vendor feed dates are DD/MM; parse explicitly.", helpful=3, harmful=1)
print(pb.render())

def apply_delta(pb: Playbook, delta: dict, next_id) -> None:
    for tag in delta.get("bullet_tags", []):              # update counters
        b = pb.bullets.get(tag["id"])
        if b and tag["tag"] == "helpful":
            b.helpful += 1
        elif b and tag["tag"] == "harmful":
            b.harmful += 1
    for lesson in delta.get("lessons", []):               # add new bullets
        if not is_duplicate(pb, lesson["text"]):          # e.g. embedding similarity > 0.9
            bid = next_id(lesson["section"])
            pb.bullets[bid] = Bullet(bid, lesson["section"], lesson["text"])

def refine(pb: Playbook) -> None:
    # Periodic cleanup: prune bullets that hurt more than they help
    for bid in list(pb.bullets):
        b = pb.bullets[bid]
        if b.harmful >= 3 and b.harmful > 2 * b.helpful:
            del pb.bullets[bid]

