import pathlib, re

ROOT = pathlib.Path("corpus")

def grep_files(pattern: str, max_hits: int = 20) -> list[dict]:
    # Search all files for a regex and return matching lines with locations
    hits, rx = [], re.compile(pattern, re.IGNORECASE)
    for p in sorted(ROOT.rglob("*.txt")):
        for n, line in enumerate(p.read_text(errors="ignore").splitlines(), 1):
            if rx.search(line):
                hits.append({"file": str(p.relative_to(ROOT)), "line": n, "text": line[:200]})
                if len(hits) >= max_hits:
                    return hits
    return hits

def open_files(paths: list[str], max_chars: int = 4000) -> dict:
    # Read a few files, truncated so outputs do not flood the context
    return {p: (ROOT / p).read_text(errors="ignore")[:max_chars] for p in paths[:3]}

